// LevelBar — Gtk.LevelBar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles levelbar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { LevelBarMode } from "@/lib/enums"

export interface LevelBarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.LevelBar */
  inverted?: boolean

  /** gdouble, from Gtk.LevelBar */
  maxValue?: number

  /** gdouble, from Gtk.LevelBar */
  minValue?: number

  /** LevelBarMode, from Gtk.LevelBar */
  mode?: LevelBarMode

  /** gdouble, from Gtk.LevelBar */
  value?: number
}

export function LevelBar({ className, children }: LevelBarProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
